<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
const props = defineProps({ alerts: Object, filters: Object, counts: Object, digest: Object });
const digest = useForm({ ...props.digest });
const filter = (key, value) => router.get(route('alerts.index'), { ...props.filters, [key]: value || undefined }, { preserveState: true, replace: true });
const acknowledge = (alert) => router.patch(route('alerts.acknowledge', alert.id), {}, { preserveScroll: true });
const resolve = (alert) => { const note = prompt('How was this alert resolved?'); if (note) router.patch(route('alerts.resolve', alert.id), { note }, { preserveScroll: true }); };
const source = (alert) => alert.source_type.includes('Advisory') ? 'Advisory' : alert.title.toLowerCase().includes('internet') ? 'Exposure' : 'Integrity';
</script>
<template><Head title="Alerts" /><AuthenticatedLayout><template #header><div><h1 class="text-2xl font-semibold">Alerts</h1><p class="text-sm text-slate-500">One inbox for exposure, device changes, and relevant advisories.</p></div></template><div class="mx-auto max-w-7xl space-y-5 px-4 py-8"><div class="grid gap-3 sm:grid-cols-3"><button @click="filter('status','open')" class="rounded-xl border bg-white p-4 text-left shadow-sm"><p class="text-xs font-semibold uppercase text-slate-500">Open</p><p class="mt-1 text-3xl font-bold">{{ counts.open || 0 }}</p></button><button @click="filter('status','acknowledged')" class="rounded-xl border bg-white p-4 text-left shadow-sm"><p class="text-xs font-semibold uppercase text-slate-500">Acknowledged</p><p class="mt-1 text-3xl font-bold">{{ counts.acknowledged || 0 }}</p></button><button @click="filter('status','resolved')" class="rounded-xl border bg-white p-4 text-left shadow-sm"><p class="text-xs font-semibold uppercase text-slate-500">Resolved</p><p class="mt-1 text-3xl font-bold">{{ counts.resolved || 0 }}</p></button></div><div class="flex flex-wrap items-center gap-3 rounded-xl border bg-white p-4 shadow-sm"><select :value="filters.status || ''" @change="filter('status',$event.target.value)" class="rounded-lg border-slate-300 text-sm"><option value="">All statuses</option><option value="open">Open</option><option value="acknowledged">Acknowledged</option><option value="resolved">Resolved</option></select><select :value="filters.severity || ''" @change="filter('severity',$event.target.value)" class="rounded-lg border-slate-300 text-sm"><option value="">All severity levels</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><select :value="filters.source || ''" @change="filter('source',$event.target.value)" class="rounded-lg border-slate-300 text-sm"><option value="">All sources</option><option value="exposure">Exposure</option><option value="integrity">Integrity</option><option value="advisory">Advisory</option></select><form @submit.prevent="digest.patch(route('alerts.digest.update'), { preserveScroll: true })" class="ml-auto flex items-center gap-2 text-sm"><label class="flex items-center gap-2"><input v-model="digest.advisory_digest_enabled" type="checkbox" class="rounded border-slate-300" /> Weekly advisory email</label><select v-model="digest.advisory_digest_day" :disabled="!digest.advisory_digest_enabled" class="rounded-lg border-slate-300 text-sm"><option v-for="day in ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']" :key="day" :value="day" class="capitalize">{{ day }}</option></select><button class="font-semibold text-teal-700">Save</button></form></div><section class="overflow-hidden rounded-xl border bg-white shadow-sm"><div v-for="alert in alerts.data" :key="alert.id" class="border-b p-5 last:border-0"><div class="flex items-start justify-between gap-4"><div><div class="flex items-center gap-2"><span class="rounded-full px-2 py-0.5 text-xs font-bold uppercase" :class="alert.severity === 'critical' ? 'bg-red-100 text-red-800' : alert.severity === 'high' ? 'bg-orange-100 text-orange-800' : 'bg-amber-100 text-amber-800'">{{ alert.severity }}</span><span class="text-xs font-semibold uppercase text-slate-500">{{ source(alert) }} / {{ alert.status }}</span></div><h2 class="mt-2 font-semibold">{{ alert.title }}</h2><p class="mt-1 text-sm text-slate-600">{{ alert.message }}</p><time class="mt-2 block text-xs text-slate-500">{{ new Date(alert.created_at).toLocaleString() }}</time></div><div v-if="alert.status !== 'resolved'" class="flex shrink-0 gap-2"><button v-if="alert.status === 'open'" @click="acknowledge(alert)" class="rounded-lg border px-3 py-2 text-xs font-semibold">Acknowledge</button><button @click="resolve(alert)" class="rounded-lg bg-emerald-700 px-3 py-2 text-xs font-semibold text-white">Resolve</button></div></div></div><p v-if="!alerts.data.length" class="py-12 text-center text-sm text-slate-500">No alerts match these filters.</p></section><div v-if="alerts.links.length > 3" class="flex justify-center gap-1"><Link v-for="link in alerts.links" :key="link.label" :href="link.url || '#'" v-html="link.label" class="rounded border px-3 py-2 text-sm" :class="{ 'bg-slate-900 text-white': link.active, 'pointer-events-none opacity-40': !link.url }" /></div></div></AuthenticatedLayout></template>
